// Read-only complete scalar codec census and exact reusable q8 join sorting.
#include <gmpxx.h>
#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <fcntl.h>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <vector>
using Clock=std::chrono::steady_clock;using Z=mpz_class;using Q=mpq_class;
constexpr uint32_t counts[]={0,4,36,386,4279,39908,293306,1651060,6958562};
void need(bool x,const std::string&s){if(!x)throw std::runtime_error(s);}
void need(bool x,const char*s){if(!x)throw std::runtime_error(s);}
double seconds(Clock::time_point t){return std::chrono::duration<double>(Clock::now()-t).count();}
uint32_t little(const unsigned char*p,int n){uint32_t v=0;for(int j=n-1;j>=0;--j)v=(v<<8)|p[j];return v;}
uint32_t big(const unsigned char*p,int n){uint32_t v=0;for(int j=0;j<n;++j)v=(v<<8)|p[j];return v;}
struct Mapped{int fd;size_t size;const unsigned char*p;explicit Mapped(const std::string&path){fd=open(path.c_str(),O_RDONLY);need(fd>=0,"open "+path);struct stat s{};need(fstat(fd,&s)==0&&s.st_size>0,"source stat");size=s.st_size;void*data=mmap(nullptr,size,PROT_READ,MAP_PRIVATE,fd,0);need(data!=MAP_FAILED,"source mmap");p=(const unsigned char*)data;}~Mapped(){munmap((void*)p,size);close(fd);}};
struct Join{uint32_t ordinal,type,permutation;};
void sort_joins(const std::string&manifest,const std::string&output,uint64_t expected){auto start=Clock::now();need(access(output.c_str(),F_OK)!=0,"fresh sorted lookup output");std::ifstream list(manifest);need(bool(list),"exact join input list");std::vector<Join>rows;rows.reserve(expected);std::string path;uint64_t files=0;
 while(std::getline(list,path)){need(!path.empty(),"nonempty join path");Mapped data(path);need(data.size%12==0,"complete join records");++files;for(size_t at=0;at<data.size;at+=12){Join row{little(data.p+at,4),little(data.p+at+4,4),little(data.p+at+8,4)};need(row.ordinal<118030185&&row.type<6958562&&row.permutation>>24==0,"join record fields");unsigned seen=0;for(int j=0;j<8;++j){int v=(row.permutation>>(3*j))&7;need(!(seen>>v&1),"exact join row permutation");seen|=1<<v;}rows.push_back(row);}}
 need(list.eof()&&rows.size()==expected,"exact full source join count");double loading=seconds(start);auto stamp=Clock::now();std::sort(rows.begin(),rows.end(),[](const Join&a,const Join&b){return a.ordinal<b.ordinal;});for(size_t i=1;i<rows.size();++i)need(rows[i-1].ordinal<rows[i].ordinal,"unique original support ordinal");double sorting=seconds(stamp);stamp=Clock::now();FILE*out=fopen(output.c_str(),"wx");need(out!=nullptr,"fresh sorted output");for(const auto&row:rows){unsigned char bytes[12];uint32_t values[]={row.ordinal,row.type,row.permutation};for(int i=0;i<3;++i)for(int j=0;j<4;++j)bytes[4*i+j]=(values[i]>>(8*j))&255;need(fwrite(bytes,1,12,out)==12,"sorted lookup serialization");}need(fclose(out)==0,"sorted lookup close");double writing=seconds(stamp);
 Mapped check(output);need(check.size==expected*12,"exact sorted output bytes");for(size_t i=0;i<rows.size();++i)need(little(check.p+12*i,4)==rows[i].ordinal&&little(check.p+12*i+4,4)==rows[i].type&&little(check.p+12*i+8,4)==rows[i].permutation,"complete sorted lookup readback");
 std::cout<<"{\"status\":\"PASS_REUSABLE_Q8_LOOKUP\",\"records\":"<<expected<<",\"source_files\":"<<files<<",\"bytes\":"<<expected*12<<",\"loading_seconds\":"<<loading<<",\"sorting_seconds\":"<<sorting<<",\"serialization_seconds\":"<<writing<<",\"complete_seconds\":"<<seconds(start)<<"}\n";}
uint64_t limb_count(const Z&v){return v==0?0:(mpz_sizeinbase(v.get_mpz_t(),2)+63)/64;}
void codec_roundtrip(const Q&q){Z numerator=q.get_num(),denominator=q.get_den();int sign=mpz_sgn(numerator.get_mpz_t());Z magnitude=abs(numerator);std::vector<uint64_t>num(limb_count(numerator)),den(limb_count(denominator));size_t n=0,d=0;if(!num.empty())mpz_export(num.data(),&n,-1,8,-1,0,magnitude.get_mpz_t());mpz_export(den.data(),&d,-1,8,-1,0,denominator.get_mpz_t());need(n==num.size()&&d==den.size(),"exact scalar limb lengths");Z nr,dr;mpz_import(nr.get_mpz_t(),n,-1,8,-1,0,num.data());mpz_import(dr.get_mpz_t(),d,-1,8,-1,0,den.data());if(sign<0)nr=-nr;Q restored(nr,dr);restored.canonicalize();need(restored==q,"exact scalar codec roundtrip");}
void census(const std::string&geometry,const std::string&jets,const std::string&type8,const std::string&scalar8,uint64_t limit){auto start=Clock::now();uint64_t all=0,scalarbytes=0,matrixbytes=0,offsetbytes=0,roundtrips=0,max_num_bits=0,max_den_bits=0,max_index=0,max_basis=0;bool full=true;std::vector<std::string>levels;
 for(int k=1;k<=8;++k){auto stamp=Clock::now();Mapped types(k==8?type8:geometry+"/q"+std::to_string(k)+".types");size_t stride=k==8?126:73;need(types.size==stride*counts[k],"complete canonical type population");std::ifstream source(k==8?scalar8:jets+"/q"+std::to_string(k)+".jets");need(bool(source),"scalar source open");std::string line;
  if(k<8){need(bool(std::getline(source,line)),"complete jet header");std::istringstream header(line);std::string magic;uint64_t level,begin,end,slots;need(bool(header>>magic>>level>>begin>>end>>slots)&&magic=="P31JETS1"&&level==uint64_t(k)&&begin==0&&end==counts[k],"accepted jet scalar source header");}
  uint64_t wanted=std::min<uint64_t>(counts[k],limit?limit:counts[k]);full&=wanted==counts[k];uint64_t sb=0,mb=0,zeros=0,negatives=0,localmaxn=0,localmaxd=0,index_membership[17][2]{};
  for(uint64_t tid=0;tid<wanted;++tid){need(bool(std::getline(source,line)),"complete scalar source row");std::istringstream input(line);uint64_t id;need(bool(input>>id)&&id==tid,"exact scalar type order");Q q;uint32_t idx;auto raw=types.p+stride*tid;int off=k==8?2:1;idx=k==8?big(raw,2):raw[0];need(idx>0&&idx<=16,"accepted proper image index width");
   if(k==8){uint32_t declared;std::string value,tail;need(bool(input>>declared>>value)&&declared==idx&&!(input>>tail),"exact q8 scalar row");q=Q(value);q.canonicalize();}
   else{Z denominator,numerator;need(bool(input>>denominator>>numerator)&&denominator>0,"exact proper scalar part");q=Q(numerator,denominator);q.canonicalize();}
   for(int i=0;i<k;++i)for(int j=0;j<=i;++j){int entry=int(raw[off++])-4;need(std::abs(entry)<=4&&(i!=j||(entry>0&&entry<=4)),"original Gram entry and norm bound");}
   uint64_t determinant=1;unsigned basis[8][8]{};for(int i=0;i<k;++i){for(int j=0;j<=i;++j){unsigned entry=k==8?big(raw+off,2):raw[off];off+=k==8?2:1;need(entry<=255,"exact image basis byte width");basis[i][j]=entry;max_basis=std::max(max_basis,uint64_t(entry));}need(basis[i][i]>0,"positive lattice diagonal");determinant*=basis[i][i];for(int j=0;j<i;++j)need(basis[i][j]<basis[i][i],"canonical image lattice residue");}need(determinant==idx,"full proper lattice index");max_index=std::max(max_index,uint64_t(idx));bool ones=true;long coordinates[8]{};if(idx!=1)for(int i=0;i<k;++i){long value=1;for(int j=0;j<i;++j)value-=basis[i][j]*coordinates[j];if(value%basis[i][i]){ones=false;break;}coordinates[i]=value/basis[i][i];}++index_membership[idx][ones?1:0];
   Z numerator=q.get_num(),denominator=q.get_den();uint64_t nl=limb_count(numerator),dl=limb_count(denominator);need(nl<=65535&&dl>0&&dl<=65535,"scalar limb-count width");uint64_t nb=numerator==0?0:mpz_sizeinbase(numerator.get_mpz_t(),2),db=mpz_sizeinbase(denominator.get_mpz_t(),2);localmaxn=std::max(localmaxn,nb);localmaxd=std::max(localmaxd,db);sb+=5+8*(nl+dl);mb+=5+3*(k*(k+1)/2);zeros+=numerator==0;negatives+=numerator<0;
   if(tid==0||tid+1==wanted||nb==localmaxn||db==localmaxd){codec_roundtrip(q);++roundtrips;}}
  if(wanted==counts[k]){while(std::getline(source,line))need(line.find_first_not_of(" \t\r\n")==std::string::npos,"complete scalar source tail");need(source.eof(),"scalar source read completion");}
  uint64_t offsets=8*(wanted+1);all+=wanted;scalarbytes+=sb;matrixbytes+=mb;offsetbytes+=offsets;max_num_bits=std::max(max_num_bits,localmaxn);max_den_bits=std::max(max_den_bits,localmaxd);std::ostringstream record;record<<"{\"k\":"<<k<<",\"types\":"<<wanted<<",\"source_types\":"<<counts[k]<<",\"scalar_payload_bytes\":"<<sb<<",\"matrix_lattice_payload_bytes\":"<<mb<<",\"offset_bytes\":"<<offsets<<",\"zeros\":"<<zeros<<",\"negatives\":"<<negatives<<",\"max_numerator_bits\":"<<localmaxn<<",\"max_denominator_bits\":"<<localmaxd<<",\"seconds\":"<<seconds(stamp)<<",\"index_membership_histogram\":[";for(int i=0;i<=16;++i){if(i)record<<',';record<<'['<<index_membership[i][0]<<','<<index_membership[i][1]<<']';}record<<"]}";levels.push_back(record.str());}
 std::cout<<"{\"status\":\"PASS_EXACT_SCALAR_CACHE_CENSUS\",\"full\":"<<(full?"true":"false")<<",\"types\":"<<all<<",\"scalar_payload_bytes\":"<<scalarbytes<<",\"matrix_lattice_payload_bytes\":"<<matrixbytes<<",\"offset_bytes\":"<<offsetbytes<<",\"level_header_bytes\":128,\"total_cache_file_bytes\":"<<scalarbytes+matrixbytes+offsetbytes+128<<",\"max_numerator_bits\":"<<max_num_bits<<",\"max_denominator_bits\":"<<max_den_bits<<",\"maximum_original_image_index\":"<<max_index<<",\"maximum_image_basis_entry\":"<<max_basis<<",\"exact_codec_roundtrips\":"<<roundtrips<<",\"complete_seconds\":"<<seconds(start)<<",\"levels\":[";for(size_t i=0;i<levels.size();++i){if(i)std::cout<<',';std::cout<<levels[i];}std::cout<<"]}\n";}
int main(int argc,char**argv){try{need(argc>=2,"cache preparation mode");std::string mode=argv[1];if(mode=="sort-joins"){need(argc==5,"join list output expected count");sort_joins(argv[2],argv[3],std::stoull(argv[4]));}else if(mode=="census"){need(argc==7,"geometry jets q8-types q8-scalars limit");census(argv[2],argv[3],argv[4],argv[5],std::stoull(argv[6]));}else throw std::runtime_error("unknown mode");return 0;}catch(const std::exception&e){std::cerr<<"REFUSED: "<<e.what()<<'\n';return 2;}}
